🚀 The feature, motivation and pitch
The current error handling logic does not immediately throw when detecting missing symbolic function for custom autograd.Function. This leads to potentially misleading error message, by errors thrown from converting the nodes after. One simple example could be
import torch


class MyAutogradNode(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        return x.max(dim=2, keepdims=True)[0].round()

class MyModule(torch.nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.conv = torch.nn.Conv1d(2, 2, 1)
        print(self.conv.weight.shape)

    def forward(self, x):
        new_weight = MyAutogradNode.apply(x)
        return self.conv._conv_forward(x, new_weight, self.conv.bias)

x = torch.randn(2, 2, 4)
m = torch.jit.trace(MyModule(), x)
torch.onnx.export(m, x, "my_module.onnx", verbose=True)
